// Extract distinct unique companies
export const ORG_COMPANIES: string[] = Array.from(new Set(ORG_HIERARCHY.map((o) => o.company)));

// Helper to get sectors for a company
export const getSectorsForCompany = (company: string): string[] => {
  const filtered = ORG_HIERARCHY.filter((o) => o.company === company);
  const sectors = Array.from(new Set(filtered.map((o) => o.sector)));
  return sectors;
};

// Helper to get divisions for a company and sector
export const getDivisionsForSector = (company: string, sector: string): string[] => {
  const filtered = ORG_HIERARCHY.filter((o) => o.company === company && (sector ? o.sector === sector : true));
  return Array.from(new Set(filtered.map((o) => o.division)));
};

// Helper to get departments for a division
export const getDepartmentsForDivision = (company: string, sector: string, division: string): string[] => {
  const filtered = ORG_HIERARCHY.filter(
    (o) => o.company === company && (sector && sector !== 'n/a' ? o.sector === sector : true) && o.division === division
  );
  return Array.from(new Set(filtered.map((o) => o.department)));
};
